@MainActor
final class DailyClothSupportExperimentTests: XCTestCase {
    /// This test also compiles in Release: the explicit R core remains the
    /// independent pre-experiment source, not a baseline regenerated by a trial.
    func testReferenceSourceRemainsFrozen() {
        let source = MobileReferenceLighting.directShadowShader(ballCount: 16, profile: .reflection)
        XCTAssertEqual(sha256(source), "8f2753a642a9e0da466389406a374fdc25fc47f0026b0dccff91efa9f8fd3495")
        XCTAssertEqual(sha256(MobileReferenceLighting.emitterGeometry),
                       "65c4665f3e1221ee507eefe9fd4e3e6513de2581fa9818a253e67e190ef3db42")
        XCTAssertFalse(source.contains("height_safe_below_mask"))
    }

    func testExplicitReferenceCompleteSurfaceRemainsFrozen() throws {
        let scene = AngleTrainingScene()
        scene.configureReferenceTableRendering()
        scene.configureClothSupportExperiment(request: .off)
        scene.setupScene(mobileRendering: true, roomStyle: .tournament)
        XCTAssertFalse(scene.safeClothSupportState.effective)
        XCTAssertEqual(scene.safeClothSupportState.fallbackReason, "not-requested")
        XCTAssertTrue(scene.applyClothColor(.green))
        XCTAssertTrue(scene.applyTableStyle(.charcoal))
        var surface: String?
        scene.tableNode?.enumerateChildNodes { node, _ in
            if surface == nil {
                surface = node.geometry?.materials.first { $0.name == "TaiNi" }?.shaderModifiers?[.surface]
            }
        }
        // Independently captured from all four successful r4 complete-scene
        // fixtures before production experiment wiring, not from this helper.
        XCTAssertEqual(sha256(try XCTUnwrap(surface)),
                       "9495698875cd01a4ecd8d00708ce88bf9989c6e118805620f99a11d03dcca390")
    }

    func testProductionDefaultInstallsGoldenGuardAcrossReferenceEntrypoints() throws {
        for entry in DefaultEntry.allCases {
            try autoreleasepool {
                let scene = makeDefaultScene(entry: entry)
                XCTAssertEqual(scene.clothSupportRequest, .guardCombo, "Entry: \(entry)")
                XCTAssertTrue(scene.safeClothSupportState.requested)
                XCTAssertTrue(scene.safeClothSupportState.effective)
                XCTAssertNil(scene.safeClothSupportState.fallbackReason)
                XCTAssertEqual(scene.safeClothSupportState.variant, DailyClothSupportExperiment.guardAlgorithmVersion)
                XCTAssertEqual(scene.safeClothSupportState.capacity, 16)
                XCTAssertEqual(scene.safeClothSupportState.profile, "R")
                XCTAssertEqual(scene.safeClothSupportState.sampling, "reference")
                XCTAssertTrue(scene.applyClothColor(.green))
                XCTAssertTrue(scene.applyTableStyle(.charcoal))
                let materials = clothMaterials(in: try XCTUnwrap(scene.tableNode))
                XCTAssertFalse(materials.isEmpty, "Entry must install real TaiNi materials: \(entry)")
                for material in materials {
                    let surface = try XCTUnwrap(material.shaderModifiers?[.surface])
                    XCTAssertEqual(sha256(surface),
                        "ca5acc70043f0da620e2c6501188063c78027c8e26b62233d128ced01f81aabd",
                        "All installed TaiNi surfaces must match the independent golden: \(entry)")
                }
            }
        }
    }

    func testProductionDefaultTemporaryTopDownSharesInstalledGuardMaterials() throws {
        let scene = makeDefaultScene()
        XCTAssertTrue(scene.safeClothSupportState.effective)
        let sourceMaterials = clothMaterials(in: try XCTUnwrap(scene.tableNode))
        XCTAssertFalse(sourceMaterials.isEmpty)
        let originals = sourceMaterials.map { ($0, $0.shaderModifiers, $0.value(forKey: "contactUniforms") as? NSData) }
        let temporary = scene.makeTemporaryTopDownRenderScene()
        let copiedMaterials = clothMaterials(in: temporary.rootNode)
        XCTAssertEqual(Set(copiedMaterials.map(ObjectIdentifier.init)), Set(sourceMaterials.map(ObjectIdentifier.init)),
                       "The temporary renderer must retain the installed material identities")
        for (material, modifiers, uniforms) in originals {
            XCTAssertEqual(material.shaderModifiers, modifiers)
            XCTAssertEqual(material.value(forKey: "contactUniforms") as? NSData, uniforms)
            XCTAssertTrue(try XCTUnwrap(material.shaderModifiers?[.surface])
                .contains("inline bool legacyConeDomain(float3 p,thread const float4 *balls) {"))
        }
    }

    func testLegacyRecipesKeepSupportExplicitlyDisabled() {
        for recipe in [TableRenderRecipe.legacyMobile, .teachingPlain, .plainLegacy, .studioLegacy] {
            autoreleasepool {
                let scene = AngleTrainingScene()
                scene.setupScene(recipe: recipe, roomStyle: .tournament)
                XCTAssertEqual(scene.clothSupportRequest, .off, "Legacy recipe: \(recipe)")
                XCTAssertFalse(scene.safeClothSupportRequested)
                XCTAssertFalse(scene.safeClothSupportState.effective)
                XCTAssertEqual(scene.safeClothSupportState.probeCacheIdentity, "off")
                for material in clothMaterials(in: scene.rootNode) {
                    let source = material.shaderModifiers?[.surface] ?? ""
                    XCTAssertFalse(source.contains("inline bool legacyConeDomain(float3 p,thread const float4 *balls) {"))
                    XCTAssertFalse(source.contains("bool height_safe_below_mask(float3 p, float4 ball) {"))
                }
            }
        }
    }

    private func sha256(_ value: String) -> String {
        SHA256.hash(data: Data(value.utf8)).map { String(format: "%02x", $0) }.joined()
    }

    // The low-level compatibility overload remains opt-in. Production material
    // installation supplies the scene's configured request explicitly.
    func testDisabledProgramPreservesExistingConfigurationsExactly() {
        for profile in MobileReferenceLighting.SpecializedProfile.allCases {
            for count in [0, 1, 16, 32, 48] {
                for masked in [false, true] {
                    for merged in [false, true] {
                        let original = MobileReferenceLighting.directShadowShader(ballCount: count, usesMask: masked,
                            profile: profile, mergesSupport: merged, factorsBRDF: true)
                        let program = MobileReferenceLighting.directShadowProgram(ballCount: count, usesMask: masked,
                            profile: profile, mergesSupport: merged, factorsBRDF: true)
                        assertFallback(program, original: original, reason: "not-requested")
                        XCTAssertFalse(program.state.requested)
                    }
                }
            }
        }
    }

    func testSupportedProgramMatchesIndependentAuditedBuilder() throws {
        let reference = MobileReferenceLighting.directShadowShader(ballCount: 16, profile: .reflection)
        let program = MobileReferenceLighting.directShadowProgram(ballCount: 16, profile: .reflection,
                                                                  safeSupportRequested: true)
        XCTAssertTrue(program.state.requested)
        XCTAssertTrue(program.state.effective)
        XCTAssertNil(program.state.fallbackReason)
        XCTAssertEqual(program.state.variant, ClothResearchShaders.identity)
        XCTAssertEqual(program.state.capacity, 16)
        XCTAssertEqual(program.state.profile, "R")
        XCTAssertEqual(program.state.sampling, "reference")
        XCTAssertEqual(program.declaration, ClothResearchShaders.heightSafeBelow + "\n")
        XCTAssertEqual(program.declarationSuffix, "")
        let prefix = "#pragma declaration\n"
        let suffix = "\n#pragma body\n"
        let before = prefix + MobileReferenceLighting.analyticPanelDiffuse + suffix + reference
        let assembled = prefix + program.declaration + MobileReferenceLighting.analyticPanelDiffuse + suffix + program.source
        XCTAssertEqual(assembled, try ClothResearchShaders.heightSafeSurface(before, ballCount: 16))
    }

