    func testRequestSelectionKeepsPlainAndGuardDistinctAndRejectsConflict() {
        typealias Request = DailyClothSupportExperiment.Request
        XCTAssertEqual(Request.resolve(arguments: []), .guardCombo)
        XCTAssertEqual(Request.resolve(arguments: ["-rendering.referenceCloth"]), .off)
        XCTAssertEqual(Request.resolve(arguments: ["-daily3D.safeClothSupport"]), .plainSafe)
        XCTAssertEqual(Request.resolve(arguments: ["-daily3D.guardClothSupport"]), .guardCombo)
        for arguments in [
            ["-daily3D.safeClothSupport", "-daily3D.guardClothSupport"],
            ["-rendering.referenceCloth", "-daily3D.safeClothSupport"],
            ["-rendering.referenceCloth", "-daily3D.guardClothSupport"],
            ["-rendering.referenceCloth", "-daily3D.safeClothSupport", "-daily3D.guardClothSupport"]
        ] {
            XCTAssertEqual(Request.resolve(arguments: arguments), .conflict)
        }
        let original = MobileReferenceLighting.directShadowShader(ballCount: 16, profile: .reflection)
        let conflict = MobileReferenceLighting.directShadowProgram(ballCount: 16, profile: .reflection,
                                                                   supportRequest: .conflict)
        assertFallback(conflict, original: original, reason: "conflicting-support-flags")
        XCTAssertTrue(conflict.state.requested)
        XCTAssertEqual(conflict.state.requestedVariant, "conflict")
        XCTAssertNotEqual(DailyClothSupportExperiment.cacheIdentity(request: .plainSafe),
                          DailyClothSupportExperiment.cacheIdentity(request: .guardCombo))
        let scene = makeScene(request: .conflict)
        XCTAssertTrue(scene.safeClothSupportRequested)
        XCTAssertFalse(scene.safeClothSupportState.effective)
        XCTAssertEqual(scene.safeClothSupportState.fallbackReason, "conflicting-support-flags")
        scene.configureReferenceTableRendering()
        XCTAssertEqual(scene.clothSupportRequest, .guardCombo)
        XCTAssertTrue(scene.safeClothSupportRequested)
        XCTAssertFalse(scene.safeClothSupportState.effective, "Reconfiguration is not shader installation")
        XCTAssertEqual(scene.safeClothSupportState.fallbackReason, "not-installed")
    }

    func testGuardUnsupportedProgramsRemainExactlyOriginal() {
        // Populate the process-wide text cache first. A hit must never bypass
        // the current caller's configuration, source or fallback checks.
        let warmed = MobileReferenceLighting.directShadowProgram(ballCount: 16, profile: .reflection,
                                                                  supportRequest: .guardCombo)
        XCTAssertTrue(warmed.state.effective)
        XCTAssertEqual(sha256(warmed.source), DailyClothSupportExperiment.guardCoreSHA256)
        for profile in MobileReferenceLighting.SpecializedProfile.allCases {
            for count in [0, 1, 32, 48] {
                let original = MobileReferenceLighting.directShadowShader(ballCount: count, profile: profile)
                let program = MobileReferenceLighting.directShadowProgram(ballCount: count, profile: profile,
                                                                          supportRequest: .guardCombo)
                assertFallback(program, original: original,
                    reason: profile == .reflection ? "unsupported-capacity" : "unsupported-profile")
                XCTAssertEqual(program.state.requestedVariant, "guard-combo")
            }
        }
        for (masked, specialized, merged, factored, prototype, reason) in [
            (false, true, false, false, false, "mask-disabled"),
            (true, false, false, false, false, "specialization-disabled"),
            (true, true, true, false, false, "merged-support-conflict"),
            (true, true, false, true, false, "factored-brdf-conflict"),
            (true, true, false, false, true, "cloth-prototype-conflict")
        ] {
            let original = MobileReferenceLighting.directShadowShader(ballCount: 16, usesMask: masked,
                specialized: specialized, profile: .reflection, mergesSupport: merged, factorsBRDF: factored)
            assertFallback(MobileReferenceLighting.directShadowProgram(ballCount: 16, usesMask: masked,
                specialized: specialized, profile: .reflection, mergesSupport: merged, factorsBRDF: factored,
                clothPrototype: prototype, supportRequest: .guardCombo), original: original, reason: reason)
        }
        let reference = MobileReferenceLighting.directShadowShader(ballCount: 16, profile: .reflection)
        for sampling in [MobileReferenceLighting.SamplingProfile.reducedShadows, .reducedReflections, .balanced] {
            let original = MobileReferenceLighting.samplingShader(reference, profile: sampling)
            assertFallback(resolve(original, sampling: sampling, supportRequest: .guardCombo),
                           original: original, reason: "unsupported-sampling")
        }
        assertFallback(resolve(reference, balanceTrial: true, supportRequest: .guardCombo),
                       original: reference, reason: "balance-trial-conflict")
        assertFallback(resolve(reference + "\n", supportRequest: .guardCombo),
                       original: reference + "\n", reason: "reference-source-drift")
        assertFallback(resolve(reference, emitter: MobileReferenceLighting.emitterGeometry + "\n", supportRequest: .guardCombo),
                       original: reference, reason: "emitter-source-drift")
        assertFallback(resolve(reference, supportRequest: .off), original: reference, reason: "not-requested")
        assertFallback(resolve(reference, supportRequest: .conflict), original: reference, reason: "conflicting-support-flags")
    }

    func testGuardTextCacheConcurrentCallsKeepGoldenAndFallbacksIsolated() {
        let reference = MobileReferenceLighting.directShadowShader(ballCount: 16, profile: .reflection)
        let emitter = MobileReferenceLighting.emitterGeometry
        let results = ConcurrentGuardResults()
        DispatchQueue.concurrentPerform(iterations: 64) { index in
            autoreleasepool {
                let mode = index % 4
                let input = mode == 1 ? reference + "\n" : reference
                let request: DailyClothSupportExperiment.Request = mode == 3 ? .off : .guardCombo
                let capacity = mode == 2 ? 48 : 16
                let program = DailyClothSupportExperiment.resolve(reference: input, emitter: emitter, requested: true,
                    capacity: capacity, profile: .reflection, sampling: .reference, usesMask: true, specialized: true,
                    mergesSupport: false, factorsBRDF: false, prototype: false, balanceTrial: false,
                    supportRequest: request)
                let state = program.state
                let common = state.request == request && state.requested == (request != .off)
                    && state.capacity == capacity && state.profile == "R" && state.sampling == "reference"
                let matches: Bool
                if mode == 0 {
                    matches = common && state.effective && state.fallbackReason == nil
                        && state.variant == DailyClothSupportExperiment.guardAlgorithmVersion
                        && program.declaration.isEmpty
                        && DailyClothSupportExperiment.sha256(program.source) == "1ab12b0e9075e014f32c73fcf30e16126c91f1b17e045a750dd7bf9c0d899a93"
                        && program.declarationSuffix.first == "\n" && program.declarationSuffix.last == "\n"
                        && DailyClothSupportExperiment.sha256(String(program.declarationSuffix.dropFirst().dropLast()))
                            == DailyClothSupportExperiment.guardHelperSHA256
                } else {
                    let reason = mode == 1 ? "reference-source-drift" : mode == 2 ? "unsupported-capacity" : "not-requested"
                    matches = common && !state.effective && state.variant == "off" && state.fallbackReason == reason
                        && program.source == input && program.declaration.isEmpty && program.declarationSuffix.isEmpty
                }
                results.record(index: index, matches: matches)
            }
        }
        let outcome = results.snapshot()
        XCTAssertEqual(outcome.count, 64)
        XCTAssertTrue(outcome.failures.isEmpty, "Concurrent cache result/fallback drift at calls \(outcome.failures)")
    }

    private final class ConcurrentGuardResults: @unchecked Sendable {
        private let lock = NSLock()
        private var count = 0
        private var failures: [Int] = []
        func record(index: Int, matches: Bool) {
            lock.lock(); defer { lock.unlock() }
            count += 1
            if !matches { failures.append(index) }
        }
        func snapshot() -> (count: Int, failures: [Int]) {
            lock.lock(); defer { lock.unlock() }
            return (count, failures)
        }
    }

    func testUnsupportedCombinationsKeepTheOriginallyRequestedProgram() {
        for profile in [MobileReferenceLighting.SpecializedProfile.reference, .shadow, .combined] {
            let original = MobileReferenceLighting.directShadowShader(ballCount: 16, profile: profile)
            assertFallback(MobileReferenceLighting.directShadowProgram(ballCount: 16, profile: profile,
                safeSupportRequested: true), original: original, reason: "unsupported-profile")
        }
        for count in [0, 1, 32, 48] {
            let original = MobileReferenceLighting.directShadowShader(ballCount: count, profile: .reflection)
            assertFallback(MobileReferenceLighting.directShadowProgram(ballCount: count, profile: .reflection,
                safeSupportRequested: true), original: original, reason: "unsupported-capacity")
        }
        for (masked, specialized, merged, factored, prototype, reason) in [
            (false, true, false, false, false, "mask-disabled"),
            (true, false, false, false, false, "specialization-disabled"),
            (true, true, true, false, false, "merged-support-conflict"),
            (true, true, false, true, false, "factored-brdf-conflict"),
            (true, true, false, false, true, "cloth-prototype-conflict")
        ] {
            let original = MobileReferenceLighting.directShadowShader(ballCount: 16, usesMask: masked,
                specialized: specialized, profile: .reflection, mergesSupport: merged, factorsBRDF: factored)
            assertFallback(MobileReferenceLighting.directShadowProgram(ballCount: 16, usesMask: masked,
                specialized: specialized, profile: .reflection, mergesSupport: merged, factorsBRDF: factored,
                safeSupportRequested: true, clothPrototype: prototype), original: original, reason: reason)
        }
    }

    func testSamplingBalanceAndSourceDriftFailClosed() {
        let reference = MobileReferenceLighting.directShadowShader(ballCount: 16, profile: .reflection)
        for sampling in [MobileReferenceLighting.SamplingProfile.reducedShadows, .reducedReflections, .balanced] {
            let original = MobileReferenceLighting.samplingShader(reference, profile: sampling)
            assertFallback(resolve(original, sampling: sampling), original: original, reason: "unsupported-sampling")
        }
        assertFallback(resolve(reference, balanceTrial: true), original: reference, reason: "balance-trial-conflict")
        assertFallback(resolve(reference, emitter: MobileReferenceLighting.emitterGeometry + "\n"),
                       original: reference, reason: "emitter-source-drift")
        for changed in [reference + "\n", reference.replacingOccurrences(of: "max(0.000001,lightCellRadius", with: "max(0.000002,lightCellRadius")] {
            assertFallback(resolve(changed), original: changed, reason: "reference-source-drift")
        }
    }

