    func testTableCacheSeparatesRequestsAndReusesTheSameVariant() async throws {
        let cache = TableResourceCache.shared
        defer { cache.purge() }
        for (firstEnabled, secondEnabled, genericReference) in [
            (false, true, false), (true, false, false), (true, false, true), (true, true, false)
        ] {
            cache.purge()
            weak var released: AngleTrainingScene?
            var firstTableID: ObjectIdentifier?
            try autoreleasepool {
                let first = makeScene(requested: firstEnabled)
                released = first
                firstTableID = ObjectIdentifier(try XCTUnwrap(first.tableNode))
                XCTAssertEqual(first.safeClothSupportState.effective, firstEnabled)
                XCTAssertEqual(try cloth(first).shaderModifiers?[.surface]?.contains("height_safe_below_mask"), firstEnabled)
            }
            try await Task.sleep(nanoseconds: 50_000_000) // existing main-actor cache release boundary
            XCTAssertNil(released)
            XCTAssertNotNil(cache.idleTable)
            let second = makeScene(requested: secondEnabled, genericReference: genericReference)
            let secondTableID = ObjectIdentifier(try XCTUnwrap(second.tableNode))
            XCTAssertEqual(secondTableID == firstTableID, firstEnabled == secondEnabled)
            XCTAssertEqual(second.safeClothSupportState.effective, secondEnabled)
            XCTAssertEqual(try cloth(second).shaderModifiers?[.surface]?.contains("height_safe_below_mask"), secondEnabled)
            let concurrent = makeScene(requested: !secondEnabled)
            XCTAssertFalse(concurrent.tableNode === second.tableNode)
            XCTAssertFalse(try cloth(concurrent) === cloth(second), "Live pages cannot share mutable materials")
            let originalOther = try cloth(concurrent).shaderModifiers
            _ = second.applyClothColor(.burgundy)
            XCTAssertEqual(try cloth(concurrent).shaderModifiers, originalOther)
        }
    }

    func testExpansionFallsBackAndUpdatesProbeIdentityWithoutChangingDefaultProbeKeys() throws {
        let scene = makeScene(requested: true)
        XCTAssertEqual(scene.contactOcclusion?.capacity, 16)
        XCTAssertTrue(scene.safeClothSupportState.effective)
        var previous = RoomReflectionProbe.Inputs(style: .tournament, scene: scene)
        for objectCount in [16, 32] {
            let keys = (0..<objectCount).map { PositionPlayBall.instanceKey(number: $0 % 15 + 1) }
            scene.configureBallInstances(keys)
            let capacity = try XCTUnwrap(scene.contactOcclusion?.capacity)
            XCTAssertEqual(capacity, objectCount + 16)
            XCTAssertTrue(scene.safeClothSupportRequested)
            XCTAssertFalse(scene.safeClothSupportState.effective)
            XCTAssertEqual(scene.safeClothSupportState.fallbackReason, "unsupported-capacity")
            XCTAssertEqual(scene.safeClothSupportState.capacity, capacity)
            let source = try XCTUnwrap(cloth(scene).shaderModifiers?[.surface])
            XCTAssertFalse(source.contains("height_safe_below_mask"))
            XCTAssertTrue(source.contains(MobileReferenceLighting.directShadowShader(ballCount: capacity, profile: .reflection)))
            let current = RoomReflectionProbe.Inputs(style: .tournament, scene: scene)
            XCTAssertNotEqual(current, previous)
            previous = current
        }
        let baseline = makeScene(requested: false)
        let originalInputs = RoomReflectionProbe.Inputs(style: .tournament, scene: baseline)
        baseline.configureBallInstances((0..<32).map { PositionPlayBall.instanceKey(number: $0 % 15 + 1) })
        XCTAssertEqual(baseline.contactOcclusion?.capacity, 48)
        XCTAssertEqual(RoomReflectionProbe.Inputs(style: .tournament, scene: baseline), originalInputs,
                       "An off experiment must not add default-path probe rebakes on ball expansion")
    }

    func testGuardCacheSeparatesOtherRequestsAndReusesGuard() async throws {
        let cache = TableResourceCache.shared
        defer { cache.purge() }
        typealias Request = DailyClothSupportExperiment.Request
        let sequence: [(Request?, Request?)] = [(.off, .guardCombo), (.plainSafe, .guardCombo),
            (.guardCombo, .off), (.guardCombo, .plainSafe), (.guardCombo, .guardCombo),
            (nil, .off), (nil, nil)]
        // Independently emitted full surfaces in support-guard-live-independent-r1.
        // Guard's explanatory comment mentions the plain helper name, so match
        // function definitions and the complete source rather than a bare token.
        let expectedSurfaceSHA: [Request: String] = [
            .off: "9495698875cd01a4ecd8d00708ce88bf9989c6e118805620f99a11d03dcca390",
            .plainSafe: "2dc79673f10c635094825df7089d451ebe891bd4433e74ddb1e6b1b9a43cf404",
            .guardCombo: "ca5acc70043f0da620e2c6501188063c78027c8e26b62233d128ced01f81aabd"
        ]
        for (firstRequest, secondRequest) in sequence {
            cache.purge()
            let firstExpected = firstRequest ?? .guardCombo
            let secondExpected = secondRequest ?? .guardCombo
            weak var released: AngleTrainingScene?
            var firstTableID: ObjectIdentifier?
            try autoreleasepool {
                let first = firstRequest.map { makeScene(request: $0) } ?? makeDefaultScene()
                released = first
                firstTableID = ObjectIdentifier(try XCTUnwrap(first.tableNode))
                XCTAssertEqual(first.safeClothSupportState.requestedVariant, firstExpected.rawValue)
            }
            try await Task.sleep(nanoseconds: 50_000_000)
            XCTAssertNil(released)
            XCTAssertNotNil(cache.idleTable)
            let second = secondRequest.map { makeScene(request: $0) } ?? makeDefaultScene()
            XCTAssertEqual(ObjectIdentifier(try XCTUnwrap(second.tableNode)) == firstTableID,
                           firstExpected == secondExpected)
            XCTAssertEqual(second.safeClothSupportState.requestedVariant, secondExpected.rawValue)
            XCTAssertEqual(second.safeClothSupportState.effective, secondExpected != .off)
            let full = try XCTUnwrap(cloth(second).shaderModifiers?[.surface])
            XCTAssertEqual(full.contains("inline bool legacyConeDomain(float3 p,thread const float4 *balls) {"),
                           secondExpected == .guardCombo)
            XCTAssertEqual(full.contains("bool height_safe_below_mask(float3 p, float4 ball) {"),
                           secondExpected == .plainSafe)
            XCTAssertEqual(sha256(full), try XCTUnwrap(expectedSurfaceSHA[secondExpected]),
                           "Prepared surface for \(firstExpected.rawValue) -> \(secondExpected.rawValue)")
            let concurrent = makeScene(request: secondExpected == .guardCombo ? .plainSafe : .guardCombo)
            XCTAssertFalse(try cloth(concurrent) === cloth(second))
            XCTAssertNotEqual(RoomReflectionProbe.Inputs(style: .tournament, scene: concurrent),
                              RoomReflectionProbe.Inputs(style: .tournament, scene: second))
        }
    }

    func testDefaultGuardExpansionFallsBackWithoutLeakingDeclarationsOrProbeIdentity() throws {
        let scene = makeDefaultScene()
        XCTAssertTrue(scene.safeClothSupportState.effective)
        var previous = RoomReflectionProbe.Inputs(style: .tournament, scene: scene)
        for count in [16, 32] {
            scene.configureBallInstances((0..<count).map { PositionPlayBall.instanceKey(number: $0 % 15 + 1) })
            XCTAssertEqual(scene.safeClothSupportState.requestedVariant, "guard-combo")
            XCTAssertEqual(scene.safeClothSupportState.capacity, count + 16)
            XCTAssertFalse(scene.safeClothSupportState.effective)
            XCTAssertEqual(scene.safeClothSupportState.fallbackReason, "unsupported-capacity")
            let full = try XCTUnwrap(cloth(scene).shaderModifiers?[.surface])
            XCTAssertFalse(full.contains("legacyConeDomain"))
            XCTAssertFalse(full.contains("height_safe_ball_mask"))
            XCTAssertTrue(full.contains(MobileReferenceLighting.directShadowShader(ballCount: count + 16, profile: .reflection)))
            let current = RoomReflectionProbe.Inputs(style: .tournament, scene: scene)
            XCTAssertNotEqual(current, previous)
            previous = current
        }
    }

    func testProbeCopiesInstalledVariantAndZeroesBallUniformsWithoutWritingSource() throws {
        let requests: [DailyClothSupportExperiment.Request?] = [nil, .plainSafe, .guardCombo]
        for request in requests {
          for style in RoomStyle.allCases {
            let scene = request.map { makeScene(request: $0, style: style) } ?? makeDefaultScene(style: style)
            XCTAssertTrue(scene.safeClothSupportState.effective, "Room styles do not change the audited R direct rig")
            let material = try cloth(scene)
            let originalSource = material.shaderModifiers
            let originalUniforms = material.value(forKey: "contactUniforms") as? NSData
            let input = try XCTUnwrap(RoomReflectionProbe.prepareBake(scene: scene, style: style))
            var copies: [SCNMaterial] = []
            input.table?.enumerateChildNodes { node, _ in
                copies += (node.geometry?.materials ?? []).filter { $0.name == "TaiNi" }
            }
            XCTAssertFalse(copies.isEmpty)
            for copied in copies {
                XCTAssertFalse(copied === material)
                XCTAssertEqual(copied.shaderModifiers, originalSource)
                let uniforms = try XCTUnwrap(copied.value(forKey: "contactUniforms") as? NSData)
                XCTAssertGreaterThan(uniforms.length, 0)
                XCTAssertEqual(uniforms as Data, Data(count: uniforms.length))
            }
            XCTAssertEqual(material.shaderModifiers, originalSource)
            XCTAssertEqual(material.value(forKey: "contactUniforms") as? NSData, originalUniforms)
          }
        }
    }

    private enum DefaultEntry: CaseIterable {
        case daily, reference, liveRecipe
    }

    /// No explicit request or argument injection: exercise actual production defaults.
    private func makeDefaultScene(entry: DefaultEntry = .daily,
                                  style: RoomStyle = .tournament) -> AngleTrainingScene {
        let scene = AngleTrainingScene()
        XCTAssertEqual(scene.clothSupportRequest, DailyClothSupportExperiment.Request.configuredDefault)
        switch entry {
        case .daily:
            scene.configureDailyClearanceRendering()
            scene.setupScene(mobileRendering: true, roomStyle: style)
        case .reference:
            scene.configureReferenceTableRendering()
            scene.setupScene(mobileRendering: true, roomStyle: style)
        case .liveRecipe:
            scene.setupScene(recipe: .liveReference, roomStyle: style)
        }
        return scene
    }

    private func clothMaterials(in root: SCNNode) -> [SCNMaterial] {
        var materials: [SCNMaterial] = []
        root.enumerateHierarchy { node, _ in
            materials += (node.geometry?.materials ?? []).filter { $0.name == "TaiNi" }
        }
        return materials
    }

    private func makeScene(requested: Bool, genericReference: Bool = false,
                           style: RoomStyle = .tournament) -> AngleTrainingScene {
        makeScene(request: requested ? .plainSafe : .off, genericReference: genericReference, style: style)
    }

    private func makeScene(request: DailyClothSupportExperiment.Request, genericReference: Bool = false,
                           style: RoomStyle = .tournament) -> AngleTrainingScene {
        let scene = AngleTrainingScene()
        if genericReference { scene.configureReferenceTableRendering() }
        else { scene.configureDailyClearanceRendering() }
        scene.configureClothSupportExperiment(request: request)
        scene.setupScene(mobileRendering: true, roomStyle: style)
        return scene
    }

    private func cloth(_ scene: AngleTrainingScene) throws -> SCNMaterial {
        var found: SCNMaterial?
        scene.tableNode?.enumerateChildNodes { node, _ in
            if found == nil { found = node.geometry?.materials.first { $0.name == "TaiNi" } }
        }
        return try XCTUnwrap(found)
    }

    private func resolve(_ reference: String, emitter: String = MobileReferenceLighting.emitterGeometry,
                         sampling: MobileReferenceLighting.SamplingProfile = .reference,
                         balanceTrial: Bool = false,
                         supportRequest: DailyClothSupportExperiment.Request? = nil) -> DailyClothSupportExperiment.Program {
        DailyClothSupportExperiment.resolve(reference: reference, emitter: emitter, requested: true,
            capacity: 16, profile: .reflection, sampling: sampling, usesMask: true, specialized: true,
            mergesSupport: false, factorsBRDF: false, prototype: false, balanceTrial: balanceTrial,
            supportRequest: supportRequest)
    }

    private func assertFallback(_ program: DailyClothSupportExperiment.Program, original: String,
                                reason: String, file: StaticString = #filePath, line: UInt = #line) {
        XCTAssertFalse(program.state.effective, file: file, line: line)
        XCTAssertEqual(program.state.variant, "off", file: file, line: line)
        XCTAssertEqual(program.state.fallbackReason, reason, file: file, line: line)
        XCTAssertEqual(program.source, original, file: file, line: line)
        XCTAssertEqual(program.declaration, "", file: file, line: line)
        XCTAssertEqual(program.declarationSuffix, "", file: file, line: line)
    }
}
